// Reopen the disposable simulation database in a different Node process.
// Any accidental provider request is rejected, never sent to the network.
import fs from 'node:fs';import path from 'node:path';import {createApp} from '../src/app.js';import {loadConfig} from '../src/config/index.js';import {hashText} from '../src/services/project-files.js';
const folder='docs/verification/nemotron-integration-20261107/mock-browser',previous=JSON.parse(fs.readFileSync(folder+'/result.json','utf8')),root=previous.fixture,checks=[];let calls=0,r;
try{r=createApp(loadConfig({DATABASE_PATH:path.join(root,'db.sqlite'),WORKSPACE_DIR:path.join(root,'projects'),BACKUP_DIR:path.join(root,'backups'),OPENROUTER_API_KEY:'FAKE_SIMULATION_ONLY',OPENROUTER_FREE_CONFIRMED:'true'}),{fetchImpl:async()=>{calls++;throw Error('Network forbidden during recovery');},messengerAutoPoll:false});
 for(const id of new Set(previous.calls.map(c=>c.job))){const d=r.team.studio.detail(id),pass=d.status==='awaiting_owner'&&!d.state.acceptedAt&&d.state.tests.executed&&d.state.tests.passed&&d.state.tests.count===2&&d.state.review.testEvidenceHash===hashText(JSON.stringify(d.state.tests))&&d.state.review.artifactHash===r.team.studio.root(d.project_id).fingerprint()&&d.executions.filter(e=>e.agent!=='application-tests').length===3&&d.usage.calls===1;checks.push({job:id,pass,review:d.state.review.decision,tests:d.state.tests.count,role:d.state.roles});}
 checks.push({name:'No provider calls or unresolved simulation locks on restart',pass:calls===0&&r.db.prepare('SELECT count(*) n FROM studio_locks').get().n===0});
 fs.writeFileSync(folder+'/restart.json',JSON.stringify({checks,passed:checks.filter(c=>c.pass).length,liveModelRequests:0,separateProcess:true},null,2));console.log(JSON.stringify({checks,liveModelRequests:0}));if(checks.some(c=>!c.pass))process.exitCode=1;
}finally{await r?.team.studio.close();r?.team.messenger.close();r?.team.preview.close();r?.team.fileActions.close();r?.db.close();}
